"""Complete cold sweetbread, chicken, lobster and layered salmon dishes."""
import pathlib,json,sqlite3,copy
root=pathlib.Path(__file__).parent
out=root.parent.parent/'outputs/SavorShelf-Content-Repairs'
db=sqlite3.connect(out/'grouped-work.sqlite3')
rows=json.loads((out/'dressing-candidates.json').read_text(encoding='utf-8'))

records={r['sourceId']:r for r in json.loads((root/'content-overrides.json').read_text(encoding='utf-8'))}
aliases={r['id']:r for r in json.loads((root/'recipe-aliases.json').read_text(encoding='utf-8'))}
newids=[]
def src(n):return json.loads(db.execute('select record from recipes where id=?',(rows[n]['id'],)).fetchone()[0])
def I(k,a,u,n,s):return dict(key=k,amount=a,unit=u,name=n,substitution=s)
def oil(a):return I('oil',a,'ml','olive oil','Use the same volume of a mild sunflower or rapeseed oil.')
def vinegar(a,kind='white wine'):return I('vinegar',a,'ml',kind+' vinegar','Use the same volume of cider vinegar for a different flavor.')
def salt(a=.5):return I('salt',a,'tsp','fine salt','Reduce or omit to taste.')
def pepper(a=.25):return I('pepper',a,'tsp','ground black pepper','Use the same amount of ground white pepper, or omit.')
def parsley(a=1):return I('parsley',a,'tsp','fresh parsley, finely chopped','Use the same amount of finely chopped chives.')
def tk(k):return '{{'+k+'}}'
STORE='Use promptly, or cover and refrigerate at 4°C (40°F) or colder for up to 3 days. Whisk again before serving; oil and vinegar naturally separate. This is a fresh dressing, not a shelf-stable preserve.'
NOTE=' Spoon measures use the app’s modern 15 ml tablespoon and 5 ml teaspoon. Yields, missing quantities and preparation times are modern estimates, not recovered historical measurements. Not kitchen-tested. Scaling changes ingredient amounts, not preparation times.'
def add(n,title,y,t,desc,items,steps,notes):
 s=src(n);r=copy.deepcopy(s['recipe']);r.update(title=title,description=desc,category='Condiments',servings=y,yieldUnit='servings',minutes=t,totalMinutes=t,ingredients=items,steps=steps,sourceStatus='adapted',versionNote='Modern measured adaptation',updatedAt='2026-09-22T20:00:00Z',notes=notes+NOTE,source=s['recipe']['source']+' SavorShelf measured adaptation.');r.pop('variants',None);r['sourceAliases']=[]
 records[r['id']]=dict(sourceId=r['id'],bodySha256=s['bodySha256'],recipe=r);newids.append(r['id']);return r
def variant(r,id,label,items,steps):r.setdefault('variants',[]).append(dict(id=id,label=label,ingredients=items,steps=steps))
def yolks(a):return I('yolks',a,'','large pasteurized egg yolks','Use 18 g commercially pasteurized liquid egg yolk per yolk; do not substitute unpasteurized raw egg.')
def mustard(a):return I('mustard',a,'tsp','dry mustard powder','Use the same volume of prepared Dijon mustard for a milder flavor.')
def cayenne():return I('cayenne',.0625,'tsp','ground cayenne pepper','Omit for a mild mayonnaise.')
def lemon(a):return I('lemon',a,'ml','lemon juice','Use the same volume of lime juice for a different flavor.')
COLD='Transfer to a clean covered container and refrigerate immediately at 4°C (40°F) or colder. Use within 3 days, using a clean spoon each time. This is fresh homemade mayonnaise, not a shelf-stable preserve.'
def emulsion(keys):
 return ['Set a clean small bowl on a damp towel to steady it. Whisk '+', '.join(tk(k) for k in keys)+' until smooth.','Measure {{oil}} into a jug. Whisk continuously while adding it drop by drop at first. Once the mixture is thick and glossy, add the remaining measured oil in a very thin stream, whisking until fully incorporated. Stop pouring if oil pools on the surface and whisk until it blends in.','The finished mayonnaise should be smooth and creamy. If it separates, put 1 teaspoon cold drinking water in a clean bowl and whisk the separated mixture into it a few drops at a time; this small repair addition changes the yield slightly.',COLD]
def eggsource(r):r['source']+=' Raw-yolk handling uses commercially pasteurized egg: https://www.foodsafety.gov/people-at-risk .';return r
def eggs(a):return I('eggs',a,'','large eggs for hard boiling','Use large pasteurized shell eggs if preferred; cook until the yolks are firm.')
def water(a,k='water'):return I(k,a,'ml','drinking water','Use the same volume of drinking water, topping up to cover as directed.')
def boil():return ['Put {{eggs}} in a saucepan with {{water}}, adding more water only if needed to cover by about 2 cm. Bring to a boil, cover, remove from heat and stand for 12 minutes. Cool under cold running water, peel and cut open; the yolks must be firm throughout.']
END='Keep covered at 4°C (40°F) or colder until serving. Refrigerate leftovers within 2 hours and use within 2 days. Do not leave the platter at room temperature for more than 2 hours.'
REF=' Cooking endpoints: https://www.foodsafety.gov/food-safety-charts/safe-minimum-internal-temperatures . Variety meats: https://ask.fsis.usda.gov/article/What-are-the-recommended-cooking-times-for-veal .'
def finish(r):r['category']='Main dishes';r['source']+=REF;return eggsource(r)

r=add(9,'Cold Sweetbreads with Mayonnaise and Aspic',4,240,'Tender sweetbreads set in a light savory jelly are coated with mayonnaise and garnished with beet, egg and additional aspic.',[I('sweetbreads',500,'g','veal sweetbreads, cleaned by an inspected butcher','Use the same weight of lamb sweetbreads from an inspected supplier; flavor differs.'),water(1500,'blanchwater'),I('stock',1000,'ml','unsalted prepared veal stock for poaching','Use the same volume of unsalted prepared chicken stock.'),I('reservedstock',300,'ml','poaching stock reserved from cooking the sweetbreads','Use the same volume of fresh unsalted prepared veal stock if needed.'),salt(.5),pepper(.25),I('mace',.125,'tsp','ground mace','Use the same amount of ground nutmeg.'),I('garlic',2,'g','peeled garlic, finely minced','Use the same weight of minced shallot.'),I('gelatin',7,'g','unflavored powdered gelatin','Use the equivalent setting strength of leaf gelatin according to its package; soak and squeeze as directed.'),water(35,'bloomwater'),I('aspicstock',120,'ml','unsalted prepared veal stock for the garnish','Use the same volume of unsalted prepared chicken stock.'),I('aspicgelatin',3,'g','unflavored powdered gelatin for the garnish','Use equivalent-strength leaf gelatin according to its package.'),water(15,'aspicwater'),I('beet',100,'g','small whole beet, scrubbed','Use the same weight of golden beet.'),water(750,'beetwater'),eggs(1),water(750),I('greens',5,'g','fresh parsley leaves for garnish','Use the same weight of chervil leaves.'),yolks(2),oil(95),vinegar(20),I('mayosalt',.125,'tsp','fine salt for the mayonnaise','Reduce or omit.')],['Put {{sweetbreads}} in a pan with {{blanchwater}}. Bring to a gentle simmer for 5 minutes, drain and discard the water. When safe to handle, trim away any remaining tough membrane and tubes.','Put the sweetbreads in a snug clean pan with {{stock}}. Simmer gently for 15–25 minutes until just firm and at least 71°C (160°F) in the center. Lift out and measure {{reservedstock}} from the poaching liquid. Spread the sweetbreads in a shallow dish, cover and refrigerate promptly for about 30 minutes until firm enough to slice.','Cut the cooled sweetbreads into neat slices about 1.5 cm thick. Return them to the pan with the measured reserved stock, {{salt}}, {{pepper}}, {{mace}} and {{garlic}}. Simmer gently for 15 minutes, then lift the pieces into a shallow serving dish in one layer.','Sprinkle {{gelatin}} over cold {{bloomwater}} and let swell for 5 minutes. Remove the seasoned stock from the heat and stir in the bloomed gelatin until dissolved. Pour over the sweetbreads. Let excess steam escape briefly, then cover and refrigerate promptly for at least 2 hours until firmly set.','For the separate garnish, sprinkle {{aspicgelatin}} over cold {{aspicwater}} and leave for 5 minutes. Heat {{aspicstock}} until steaming, remove from heat and stir in the bloomed gelatin until dissolved. Pour into a small shallow container and refrigerate for at least 2 hours until firm, then cut into small cubes.','While the jellies chill, simmer {{beet}} in {{beetwater}} for 30–45 minutes until tender. Drain, cool briefly, rub off the skin and cut into thin slices or small decorative shapes. Refrigerate until needed.']+boil()+['Slice the cooled hard-boiled egg into rounds or small wedges and refrigerate. Wash and dry {{greens}}.','Whisk {{yolks}}, {{vinegar}} and {{mayosalt}} in a clean bowl. Gradually whisk in {{oil}}, drop by drop at first and then in a thin stream, until smooth and creamy. Keep refrigerated.','Spread the mayonnaise over the cold set sweetbreads. Arrange the separate aspic cubes, beet, cooked egg and parsley around and over the platter. Serve cold.',END],'The original sweetbread paragraph and full garnish are retained. A modern 500 g pair and 300 ml reserved poaching stock are supplied. The quarter-ounce leaf gelatin becomes 7 g powdered gelatin with its own bloom water; it is added after simmering instead of boiled for fifteen minutes. The additional aspic garnish has a complete separate recipe. Mayonnaise follows the same book’s three-yolk/oil/vinegar proportions at a smaller modern size. Total time includes setting; the beet, egg and mayonnaise can be prepared during chilling.');finish(r)

r=add(10,'Kuře s Majonézou — Chilled Chicken with Mayonnaise',6,240,'Butter-braised chicken is chilled, coated in a rich six-yolk lemon mayonnaise and served with lettuce hearts and hard-boiled eggs.',[I('chicken',1400,'g','whole oven-ready chicken, giblets removed','Use two small oven-ready chickens of the same total weight; check each bird for doneness.'),I('chickensalt',6,'g','fine salt for the chicken','Reduce or omit.'),I('rubjuice',15,'ml','lemon juice for the chicken','Use the same volume of lime juice.'),I('butter',40,'g','unsalted butter','Use the same weight of neutral vegetable oil.'),I('parsley',10,'g','fresh parsley sprigs','Use the same weight of chervil sprigs.'),I('stock',350,'ml','unsalted prepared beef stock','Use the same volume of unsalted prepared chicken stock.'),yolks(6),oil(150),lemon(30),salt(.5),pepper(.25),I('lettuce',120,'g','small lettuce hearts, washed and dried','Use the same weight of pale romaine hearts.'),eggs(2),water(1000)],['Heat the oven to 170°C (340°F). Pat {{chicken}} dry; do not rinse raw poultry. Season inside and out with {{chickensalt}}, tuck the wings under and loosely secure the legs with kitchen string. Rub the breast with {{rubjuice}}.','Put {{butter}}, {{parsley}} and {{stock}} in a snug lidded ovenproof casserole. Set the chicken breast-side up on top, cover and braise for about 1½–2 hours. Check occasionally that liquid remains, adding a little hot water if needed. The thickest breast and inner thigh must both reach 74°C (165°F), avoiding bone with the thermometer.','Lift the chicken out, remove the string and rest for 10 minutes. Cut into serving pieces, remove any loose bones and spread in a shallow container. Cover and refrigerate promptly, within 2 hours of cooking, for about 1–1½ hours until cold. Discard the parsley; the cooking liquid is not part of the cold mayonnaise.']+boil()+['Quarter the cooled cooked eggs and refrigerate. Whisk {{yolks}} in a clean bowl and gradually whisk in {{oil}}, drop by drop at first, then in a thin stream until smooth. Gradually add {{lemon}}, {{salt}} and {{pepper}}.','Coat each cold chicken piece with some of the mayonnaise and arrange on a platter. Spoon the remaining mayonnaise over the chicken and surround it with {{lettuce}} and the cooked egg quarters. Serve cold.',END],'The original Czech zašpejluj is interpreted as securing the bird, not adding lard or bacon. Kitchen string is a modern substitute for skewers. The missing chicken size, braising quantities, cooking time and cooling method are supplied. Six yolks are retained; the small glass of oil becomes an explicit modern 150 ml. The original melted-butter sauce alternative is preserved in full.');finish(r)
vi=[I('mayobutter',140,'g','unsalted butter for the mayonnaise','Use the olive-oil base recipe if preferred.') if i['key']=='oil' else copy.deepcopy(i) for i in r['ingredients']];vs=copy.deepcopy(r['steps']);vs[4]='Quarter the cooled cooked eggs and refrigerate. Melt {{mayobutter}} gently, then cool until just lukewarm and still liquid, about 35–40°C (95–104°F). Whisk {{yolks}} in a clean bowl and add the melted butter drop by drop at first, then in a thin stream. Gradually whisk in {{lemon}}, {{salt}} and {{pepper}}. The butter mayonnaise firms when chilled.';variant(r,'butter-mayonnaise','Chilled chicken with butter mayonnaise',vi,vs);r['notes']+=' The butter sauce uses an explicit modern 140 g working amount rather than converting oil volume directly into butter weight.'

r=add(17,'Langosta a la Mayonesa — Chilled Lobster Platter',2,100,'A whole lobster cooked in onion-and-wine broth is chilled and split for serving with a small bowl of lemon mayonnaise.',[I('lobster',850,'g','whole raw lobster, freshly and humanely dispatched by the fishmonger, kept chilled','Use a similar-sized whole raw spiny lobster prepared by the fishmonger; cooking time varies with size.'),water(3000,'brothwater'),I('brothsalt',45,'g','salt for the lobster broth','Reduce to taste; use drinking water, not untreated seawater.'),I('onion',150,'g','peeled onion, quartered','Use the same weight of shallots.'),I('peppercorns',1,'tsp','whole black peppercorns','Use the same amount of white peppercorns.'),I('wine',75,'ml','dry sherry','Use the same volume of dry white wine, or unsalted vegetable stock for a different flavor.'),eggs(2),water(1000),I('lettuce',60,'g','lettuce hearts, washed and dried','Use the same weight of romaine hearts.'),I('garnishlemon',.5,'','lemon for garnish, washed','Use half a lime for a different flavor.'),yolks(2),oil(45),lemon(5),vinegar(.25),salt(.125),pepper(.0625)],['Put {{brothwater}}, {{brothsalt}}, {{onion}} and {{peppercorns}} in a pot large enough for the lobster. Bring to a boil and simmer for 10 minutes.','Lower {{lobster}} into the broth, adding hot water if needed to cover. Return to a gentle boil and cook for about 18–22 minutes for this size, adding {{wine}} about halfway through. Check the thickest tail meat: it must reach 63°C (145°F), turn opaque and become firm. Larger lobsters take longer.','Lift out and drain. Let cool just enough to handle, then split lengthwise on a stable cutting board with a sturdy sharp knife, protecting your hand from the sharp shell. Remove the stomach sac behind the head and the dark intestinal vein in the tail. Leave the meat in the two shell halves. Put in a shallow container and refrigerate promptly, within 2 hours, until cold, about 45–60 minutes.']+boil()+['Keep the cooked yolks for garnish and refrigerate the whites for another dish. Wash and dry {{lettuce}} and cut {{garnishlemon}} into wedges.','Whisk {{yolks}}, {{vinegar}}, {{salt}} and {{pepper}} in a clean bowl. Gradually whisk in {{oil}} drop by drop until smooth, then slowly whisk in {{lemon}}. Put the mayonnaise in a small serving bowl.','Arrange the cold lobster halves on a platter with the lettuce, cooked yolks and lemon wedges. Serve with the mayonnaise separately, allowing diners to remove the meat from the shells.',END],'The full original cooking reference includes onion, peppercorns and wine. Modern quantities, salted drinking water and a measured cooking endpoint are supplied. The lobster is purchased already dispatched by the fishmonger. Prompt shallow-container chilling replaces cooling in a large pot of broth. The source separate-sauce presentation is retained; the eggs, lettuce and lemon are a measured serving garnish. Mayonnaise follows the book’s small, yolk-rich formula.');finish(r)

r=add(21,'Guatemalan Layered Salmon and Chicken Mayonnaise',8,120,'Cold salmon and chopped chicken are layered with lettuce and a rich butter mayonnaise containing cooked and pasteurized yolks.',[I('salmon',600,'g','boneless skinless salmon fillet','Use the same weight of trout fillet for a different flavor.'),water(1000,'fishwater'),I('chicken',400,'g','boneless skinless chicken breast','Use the complete lobster variation for the original seafood alternative.'),I('stock',750,'ml','unsalted prepared chicken stock','Use the same volume of unsalted prepared vegetable stock.'),I('butter',225,'g','unsalted butter, softened','Use the same weight of a block-style dairy-free butter alternative; texture differs.'),oil(75),eggs(2),water(1000),yolks(2),pepper(.25),salt(.5),vinegar(5),I('lettuce',150,'g','tender lettuce leaves, washed and dried','Use the same weight of butterhead lettuce.')],['Bring {{fishwater}} to a bare simmer in a wide pan. Add {{salmon}} and poach gently for 8–12 minutes until the thickest part reaches 63°C (145°F) and flakes easily. Lift out, drain and break into large flakes, checking carefully for bones.','Bring {{stock}} to a gentle simmer in another pan. Add {{chicken}} and poach for about 15–20 minutes until the thickest part reaches 74°C (165°F). Lift out, drain and cut into small pieces.','Spread the cooked salmon and chicken in separate shallow containers, cover and refrigerate promptly, within 2 hours of cooking, for about 45 minutes until cold.']+boil()+['Reserve the cooked whites for another dish. Push the cooked yolks through a fine sieve into a bowl and beat with {{butter}} until smooth. Beat in {{yolks}}, {{salt}} and {{pepper}}, then add {{oil}} very slowly while beating until evenly blended. Add {{vinegar}} drop by drop.','Finely shred {{lettuce|0.3333333333333333}} and fold into the butter mayonnaise. Keep {{lettuce|0.6666666666666666}} whole for the final garnish.','Spread half the cold salmon on a platter, add one third of the mayonnaise, then half the chopped chicken. Repeat the salmon, another third of the mayonnaise and the remaining chicken. Finish with the last third of the mayonnaise and garnish with the reserved lettuce leaves.','Refrigerate the assembled platter for 15 minutes before serving. The butter dressing becomes firmer when cold; serve in modest portions.',END],'The original half pound of butter becomes a rounded modern 225 g. A small glass of oil becomes 75 ml. Missing fish, poultry, lettuce and seasoning quantities are supplied. Two cooked and two uncooked yolks are retained, with commercially pasteurized yolks for the uncooked part. The complete source’s chicken-or-lobster layering is preserved in a named variation. The shorter source entry is the opening of this same original paragraph, not a separate dish.');finish(r)
vi=[I('lobstermeat',400,'g','raw lobster tail meat, removed from the shells','Use the chicken base recipe if preferred.') if i['key']=='chicken' else dict(i,name='unsalted prepared vegetable stock',substitution='Use the same volume of drinking water with a pinch of salt.') if i['key']=='stock' else copy.deepcopy(i) for i in r['ingredients']];vs=copy.deepcopy(r['steps']);vs[1]='Bring {{stock}} to a gentle simmer in another pan. Add {{lobstermeat}} and poach for about 6–10 minutes until opaque, firm and at least 63°C (145°F) in the thickest piece. Lift out, drain and cut into small pieces.';vs=[t.replace('chicken','lobster') for t in vs];variant(r,'lobster','Layered salmon and lobster mayonnaise',vi,vs)
s=src(20);aliases[s['id']]=dict(id=s['id'],canonicalId=r['id'],bodySha256=s['bodySha256'],reason='Truncated opening of the same single original Salmon a la Mayonesa paragraph; full ingredients and layering retained in canonical source21.');r['sourceAliases'].append(s['id']);r['source']+=' Equivalent source retained: '+s['recipe']['source'];records.pop(s['id'],None)

assert len(newids)==4,len(newids)
(root/'content-overrides.json').write_text(json.dumps(list(records.values()),ensure_ascii=False,indent=2),encoding='utf-8')
(root/'recipe-aliases.json').write_text(json.dumps(list(aliases.values()),ensure_ascii=False,indent=2),encoding='utf-8')
for id in newids:db.execute('insert or replace into decisions values(?,?,?,?,?)',(id,records[id]['bodySha256'],'prepared-adaptation','Full cold main dish and all sauce and garnish components completed from original sources','repair-batch-023.py'))
db.execute('insert or replace into decisions values(?,?,?,?,?)',(s['id'],s['bodySha256'],'prepared-merge',aliases[s['id']]['reason'],'repair-batch-023.py'))
db.commit();print(json.dumps(dict(newAdaptations=len(newids),newMergedSources=1,totalOverrides=len(records),totalAliases=len(aliases))))

